fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    // Ensure values is non-empty as per the problem statement
    assert!(!values.is_empty(), "replacement values array must be non-empty");
    
    let mut result = Vec::with_capacity(a.len());
    let values_len = values.len();
    
    for i in 0..a.len() {
        if mask[i] {
            // Use i modulo values_len to index into values
            let replacement_index = i % values_len;
            result.push(values[replacement_index]);
        } else {
            result.push(a[i]);
        }
    }
    
    result
}